evaluation.reference:
Algoritmo Buscar
  Dimension v[5] Como Entero;
  Para i <- 0 Hasta 4 Hacer
    Leer v[i];
  FinPara
  Definir buscado Como Entero;
  Leer buscado;
  Definir posicion Como Entero <- -1;
  Para i <- 0 Hasta 4 Hacer
    Si v[i] = buscado Entonces
      posicion <- i;
      Salir;
    FinSi
  FinPara
  Escribir posicion;
FinAlgoritmo

